variants = {
    'current': amounts_source,
    'A-only': amounts_source.replace(early, '', 1),
    'B-only': amounts_source.replace(rounded, '    return int(Decimal(value) * 100)', 1),
}
expected = {'1.005': 101, '-1.005': -101, '2.34': 234}
original = sys.modules.get('amounts')
try:
    for label, source in variants.items():
        amounts = types.ModuleType('amounts')
        exec(compile(source, 'amounts.py', 'exec'), amounts.__dict__)
        sys.modules['amounts'] = amounts
        invoice = types.ModuleType('invoice')
        exec(compile(invoice_source, 'invoice.py', 'exec'), invoice.__dict__)
        observed = {value: invoice.invoice_total(value) for value in expected}
        print(f'{label}: ' + ', '.join(f'{value}: {observed[value]} (required {expected[value]})' for value in expected))
        if label != 'B-only':
            assert observed == expected
        else:
            assert observed == {'1.005': 100, '-1.005': -100, '2.34': 234}
finally:
    if original is None:
        sys.modules.pop('amounts', None)
    else:
        sys.modules['amounts'] = original
